const { chromium } = require('playwright');
const path = require('path');
const fs = require('fs');

const LOGO_BASE64 = `

`;

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  const htmlPath = path.resolve(__dirname, 'output.html');
  const pdfPath = path.resolve(__dirname, 'output.pdf');

  await page.goto(`file://${htmlPath}`, {
    waitUntil: 'networkidle'
  });

  await page.pdf({
  path: pdfPath,
  format: 'A4',
  printBackground: true,

  displayHeaderFooter: true,

  headerTemplate: `
    <div style="
      width: 100%;
      font-size: 10px;
      padding: 0 15mm;
      display: flex;
      align-items: center;
      justify-content: space-between;
      box-sizing: border-box;
    ">
      <img
  src="data:image/png;base64,${LOGO_BASE64}"
  style="height: 68px;"
/>
      <span style="color:#6b7280;">
        Informe de Riesgo de Incendio
      </span>
    </div>
  `,

  footerTemplate: `
    <div style="
      width: 100%;
      font-size: 9px;
      padding: 0 15mm;
      display: flex;
      align-items: center;
      justify-content: space-between;
      color: #6b7280;
      box-sizing: border-box;
    ">
      <span>Arcadia Atlas · AtlasBioscan</span>
      <span>Página <span class="pageNumber"></span> / <span class="totalPages"></span></span>
    </div>
  `,

  margin: {
    top: '30mm',
    right: '15mm',
    bottom: '25mm',
    left: '15mm'
  }
});

  await browser.close();
  console.log('✅ PDF generado:', pdfPath);
})();
